<script module lang="ts">
/**
 * A date range *field* with two segmented entries and a calendar popup (`design/components/date-range-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/popover'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentDateRange,
  agentMember,
  anchorProps,
  attributes,
  calendarDateOf,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  eraseSegment,
  fieldSegments,
  joinSlot,
  normalizeProps,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button.svelte'
import DateRangePickerRangeCalendar from './DateRangePickerRangeCalendar.svelte'
import type { CalendarDate, CalendarMessages } from './Calendar.svelte'

export interface DateRange {
  start: CalendarDate
  end: CalendarDate
}

export type DateRangePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseRange: string
}

export interface DateRangePickerProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * DatePicker's clear button: reports `onChange(null)` and resets both groups to placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: DateRange | null
  disabled?: boolean
  endName?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Also orders the segments and picks the separators.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DateRangePickerMessages
  /**
   * react-aria's validation, forwarded. A typed date outside the bounds marks the field invalid.
   * React Aria marks a reversed pair (end before start) invalid on both halves.
   */
  minValue?: CalendarDate
  onChange?: (value: DateRange | null) => void
  /**
   * Same as DatePicker (`date-picker.md`, the conventions' sheet presentation). `'auto'` shows
   * the popup as a sheet below `30rem`, with RangeCalendar unchanged inside it. `'popover'`
   * keeps the popover at every width. The anchored-range keyboard model, the two-stage Escape
   * and the focus hand-off work the same after re-anchoring.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Two hidden inputs serialize ISO-8601, as DatePicker does, once per end, because one `name`
   * cannot carry two values.
   */
  startName?: string
  /**
   * Both ends or `null`. A half-entered range is never reported. `onChange` fires when the
   * second end is committed, and clearing reports `null`. Uses `CalendarDate`, never `Date`
   * (Calendar's law).
   */
  value?: DateRange | null
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  clearable = false,
  defaultOpen,
  defaultValue,
  disabled = false,
  endName,
  firstDayOfWeek,
  id: idOwn,
  invalid: invalidOwn = false,
  isDateUnavailable,
  locale,
  maxValue,
  messages,
  minValue,
  onChange,
  presentation = 'auto',
  size = 'md',
  startName,
  value,
}: DateRangePickerProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let browserLanguage = $state(undefined as string | undefined)
// svelte-ignore state_referenced_locally
let startDraft = $state(
  dateFieldDraft((value !== undefined ? value : defaultValue)?.start, {
    locale: locale ?? browserLanguage ?? 'en-US',
    parts: ['year', 'month', 'day'] as const,
  }),
)
// svelte-ignore state_referenced_locally
let endDraft = $state(
  dateFieldDraft((value !== undefined ? value : defaultValue)?.end, {
    locale: locale ?? browserLanguage ?? 'en-US',
    parts: ['year', 'month', 'day'] as const,
  }),
)
let typed = $state('')
// svelte-ignore state_referenced_locally
let reported = $state(
  ((given) =>
    given === null || given === undefined
      ? ''
      : `${given.start.toString()}/${given.end.toString()}`)(
    value !== undefined ? value : defaultValue,
  ),
)
let anchored = $state(false)
let anchor = $state<HTMLElement | null>(null)
let field = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const say = $derived(
  messages ?? {
    previousMonth: 'Previous month',
    nextMonth: 'Next month',
    showCalendar: 'Show calendar',
    clear: 'Clear',
    chooseRange: 'Choose a date range',
  },
)
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const sheeting = $derived(presentation === 'auto' && phone.current)
const fieldOptions = $derived({ locale: language, parts: ['year', 'month', 'day'] as const })
const startSegments = $derived(fieldSegments(startDraft, fieldOptions))
const endSegments = $derived(fieldSegments(endDraft, fieldOptions))
const rangeOf = $derived(
  (
    start: ReturnType<typeof dateFieldDraft>,
    end: ReturnType<typeof dateFieldDraft>,
  ): DateRange | null => {
    const from = dateFieldValue(start, fieldOptions)
    const to = dateFieldValue(end, fieldOptions)
    return from === null || to === null
      ? null
      : { start: calendarDateOf(from), end: calendarDateOf(to) }
  },
)
const range = $derived(rangeOf(startDraft, endDraft))
const bounds = $derived({ min: minValue, max: maxValue, unavailable: isDateUnavailable })
const fieldInvalid = $derived(
  invalid ||
    dateOutOfBounds(dateFieldValue(startDraft, fieldOptions), bounds) ||
    dateOutOfBounds(dateFieldValue(endDraft, fieldOptions), bounds) ||
    (range !== null && range.end.compare(range.start) < 0),
)
const showClear = $derived(clearable && range !== null && !disabled)
const report = $derived(
  (start: ReturnType<typeof dateFieldDraft>, end: ReturnType<typeof dateFieldDraft>): void => {
    startDraft = start
    endDraft = end
    const after = rangeOf(start, end)
    const text = after === null ? '' : `${after.start.toString()}/${after.end.toString()}`
    if (text !== reported) {
      reported = text
      onChange?.(after)
    }
  },
)
const startCommit = $derived((next: ReturnType<typeof dateFieldDraft>): void =>
  report(next, endDraft),
)
const endCommit = $derived((next: ReturnType<typeof dateFieldDraft>): void =>
  report(startDraft, next),
)
const clear = $derived((): void => {
  report({}, {})
  field?.querySelector<HTMLElement>('[data-segment]')?.focus()
})
const segmentName = $derived((type: string): string => {
  try {
    return new Intl.DisplayNames(language, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = $derived((from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const startInput = $derived(
  (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
    event.preventDefault()
    if (segment.type === 'literal' || !!disabled) return
    const data = (event as InputEvent).data ?? ''
    for (const key of data) {
      const next = typeIntoSegment(startDraft, segment.type, typed, key, fieldOptions)
      typed = next.typed
      startCommit(next.draft)
      if (next.advance) {
        moveSegment(event.currentTarget, 1)
        break
      }
    }
  },
)
const endInput = $derived(
  (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
    event.preventDefault()
    if (segment.type === 'literal' || !!disabled) return
    const data = (event as InputEvent).data ?? ''
    for (const key of data) {
      const next = typeIntoSegment(endDraft, segment.type, typed, key, fieldOptions)
      typed = next.typed
      endCommit(next.draft)
      if (next.advance) {
        moveSegment(event.currentTarget, 1)
        break
      }
    }
  },
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen,
      modal: sheeting,
      positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
      ids: id === undefined ? undefined : { anchor: id },
      initialFocusEl: () =>
        (sheetPanel ?? panel)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
      onEscapeKeyDown: (details) => {
        anchored && details.preventDefault()
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const choose = $derived((next: DateRange): void => {
  report(dateFieldDraft(next.start, fieldOptions), dateFieldDraft(next.end, fieldOptions))
  api.setOpen(false)
})
const startKeys = $derived(
  (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
    if (segment.type === 'literal') return
    if (event.altKey && event.key === 'ArrowDown') {
      event.preventDefault()
      if (!disabled) api.setOpen(true)
      return
    }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault()
      typed = ''
      moveSegment(
        event.currentTarget,
        (event.key === 'ArrowRight') ===
          (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
          ? 1
          : -1,
      )
      return
    }
    if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
    const editable = !disabled
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault()
      typed = ''
      if (editable)
        startCommit(
          stepSegment(startDraft, segment.type, event.key === 'ArrowUp' ? 1 : -1, fieldOptions),
        )
      return
    }
    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault()
      typed = ''
      if (!editable) return
      if (startDraft[segment.type] === undefined) moveSegment(event.currentTarget, -1)
      else startCommit(eraseSegment(startDraft, segment.type, fieldOptions))
      return
    }
    if (event.key.length !== 1) return
    event.preventDefault()
    if (editable)
      ((key: string): void => {
        const next = typeIntoSegment(startDraft, segment.type, typed, key, fieldOptions)
        typed = next.typed
        startCommit(next.draft)
        if (next.advance) moveSegment(event.currentTarget, 1)
      })(event.key)
  },
)
const endKeys = $derived(
  (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
    if (segment.type === 'literal') return
    if (event.altKey && event.key === 'ArrowDown') {
      event.preventDefault()
      if (!disabled) api.setOpen(true)
      return
    }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault()
      typed = ''
      moveSegment(
        event.currentTarget,
        (event.key === 'ArrowRight') ===
          (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
          ? 1
          : -1,
      )
      return
    }
    if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
    const editable = !disabled
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault()
      typed = ''
      if (editable)
        endCommit(
          stepSegment(endDraft, segment.type, event.key === 'ArrowUp' ? 1 : -1, fieldOptions),
        )
      return
    }
    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault()
      typed = ''
      if (!editable) return
      if (endDraft[segment.type] === undefined) moveSegment(event.currentTarget, -1)
      else endCommit(eraseSegment(endDraft, segment.type, fieldOptions))
      return
    }
    if (event.key.length !== 1) return
    event.preventDefault()
    if (editable)
      ((key: string): void => {
        const next = typeIntoSegment(endDraft, segment.type, typed, key, fieldOptions)
        typed = next.typed
        endCommit(next.draft)
        if (next.advance) moveSegment(event.currentTarget, 1)
      })(event.key)
  },
)
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  browserLanguage = globalThis.navigator?.language
}
watchEffect(effect1)
const effect2 = () => {
  syncTriggerAnchor(anchor, api.getTriggerProps(), api.open)
}
watchEffect(effect2, { watch: () => api.open })
const effect3 = () => {
  value !== undefined &&
    (value !== null || range !== null) &&
    ((startDraft = dateFieldDraft(value?.start, fieldOptions)),
    (endDraft = dateFieldDraft(value?.end, fieldOptions)),
    (reported = ((given) =>
      given === null || given === undefined
        ? ''
        : `${given.start.toString()}/${given.end.toString()}`)(value)))
}
watchEffect(effect3, { watch: () => value, mount: false })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'DateRangePicker',
    element: () => field,
    state: () => ({
      value: range === null ? '' : `${range.start.toString()}/${range.end.toString()}`,
      open: api.open,
      disabled: disabled,
      invalid: fieldInvalid,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          ((next) =>
            report(
              dateFieldDraft(next.start, fieldOptions),
              dateFieldDraft(next.end, fieldOptions),
            ))(agentDateRange(value, bounds)),
      },
      clear: () => report({}, {}),
      open: () => api.setOpen(true),
      close: () => api.setOpen(false),
    },
    withholds: () => [field, sheetPanel ?? panel],
  })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={field}
    {...attributes(api.getAnchorProps())}
    class={styles.field}
    role="group"
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-disabled={(disabled) ? 'true' : undefined}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(fieldInvalid) ? '' : undefined}
    data-state={api.open ? 'open' : 'closed'}
    data-member="date-range-picker"
    ><div class={styles.segments} data-size={size}
      >{#each startSegments as segment, at (`start-${segment.type}-${at}`)
        }{#if segment.type === 'literal'
          }<span class={styles.separator} aria-hidden="true">{segment.text}</span
        >{:else
          }<div
            class={styles.segment}
            role="spinbutton"
            id={`${uid}-start-${segment.type}`}
            aria-label={`${'Start date'}, ${segmentName(segment.type)}`}
            aria-labelledby={(ariaLabelledby) ? `${ariaLabelledby} ${uid}-start-${segment.type}` : undefined}
            aria-describedby={ariaDescribedby}
            aria-valuenow={segment.placeholder ? undefined : segment.value}
            aria-valuemin={segment.min}
            aria-valuemax={segment.max}
            aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
            aria-required={(ariaRequired) ? 'true' : undefined}
            aria-disabled={(disabled) ? 'true' : undefined}
            aria-invalid={(fieldInvalid) ? 'true' : undefined}
            contenteditable={(!disabled) ? 'true' : undefined}
            inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
            spellcheck="false"
            tabindex={(disabled ? undefined : '0') as never}
            data-segment={segment.type}
            data-placeholder={(segment.placeholder) ? '' : undefined}
            data-disabled={(disabled) ? '' : undefined}
            onfocus={() => { typed = '' }}
            onkeydown={(event) => { startKeys(event, segment) }}
            onbeforeinput={(event) => { startInput(event, segment) }}
            >{segment.text
          }</div
        >{/if
      }{/each
    }</div
    ><span class={styles.dash} aria-hidden="true">–</span
    ><div class={styles.segments} data-size={size}
      >{#each endSegments as segment, at (`end-${segment.type}-${at}`)
        }{#if segment.type === 'literal'
          }<span class={styles.separator} aria-hidden="true">{segment.text}</span
        >{:else
          }<div
            class={styles.segment}
            role="spinbutton"
            id={`${uid}-end-${segment.type}`}
            aria-label={`${'End date'}, ${segmentName(segment.type)}`}
            aria-labelledby={(ariaLabelledby) ? `${ariaLabelledby} ${uid}-end-${segment.type}` : undefined}
            aria-describedby={ariaDescribedby}
            aria-valuenow={segment.placeholder ? undefined : segment.value}
            aria-valuemin={segment.min}
            aria-valuemax={segment.max}
            aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
            aria-required={(ariaRequired) ? 'true' : undefined}
            aria-disabled={(disabled) ? 'true' : undefined}
            aria-invalid={(fieldInvalid) ? 'true' : undefined}
            contenteditable={(!disabled) ? 'true' : undefined}
            inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
            spellcheck="false"
            tabindex={(disabled ? undefined : '0') as never}
            data-segment={segment.type}
            data-placeholder={(segment.placeholder) ? '' : undefined}
            data-disabled={(disabled) ? '' : undefined}
            onfocus={() => { typed = '' }}
            onkeydown={(event) => { endKeys(event, segment) }}
            onbeforeinput={(event) => { endInput(event, segment) }}
            >{segment.text
          }</div
        >{/if
      }{/each
    }</div
    ><span class={styles.spacer}></span
    >{#if startName !== undefined
      }<input
        type="hidden"
        name={startName}
        value={range?.start.toString() ?? ''}
        disabled={(disabled) ? true : undefined}
    />{/if
    }{#if endName !== undefined
      }<input
        type="hidden"
        name={endName}
        value={range?.end.toString() ?? ''}
        disabled={(disabled) ? true : undefined}
    />{/if
    }{#if showClear
      }<button class={styles.clear} type="button" aria-label={say.clear} onclick={() => { clear() }}
        ><Icon name="clear" {size}
      /></button
    >{/if
    }<span
      bind:this={anchor}
      {...attributes(anchorProps(api.getTriggerProps()))}
      class={triggerAnchor.anchor}
      ><Button
        variant="ghost"
        tone="neutral"
        {size}
        iconOnly={true}
        icon="calendar"
        label={say.showCalendar}
        {disabled}
    /></span
  ></div
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.content}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={say.chooseRange}
          data-member="date-range-picker"
          ><DateRangePickerRangeCalendar
            value={range}
            {minValue}
            {maxValue}
            {isDateUnavailable}
            locale={language}
            {firstDayOfWeek}
            {disabled}
            messages={say}
            label={say.chooseRange}
            onCommit={(event) => { choose(event) }}
            onAnchorChange={(event) => { anchored = event }}
        /></div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          {...attributes(api.getContentProps())}
          class={sheet.panel}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={say.chooseRange}
          aria-modal="true"
          data-presentation="sheet"
          ><div class={styles.sheetBody} data-member="date-range-picker"
            ><DateRangePickerRangeCalendar
              value={range}
              {minValue}
              {maxValue}
              {isDateUnavailable}
              locale={language}
              {firstDayOfWeek}
              {disabled}
              messages={say}
              label={say.chooseRange}
              onCommit={(event) => { choose(event) }}
              onAnchorChange={(event) => { anchored = event }}
          /></div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
